query.text:

declare @user_id0 int = @@userId, @q nvarchar(MAX), @key nvarchar(MAX), @order nvarchar(MAX)
set nocount on
SELECT TOP 0 @@fields into #t from @@table a
SELECT @key = ' WHERE EXISTS (select 1 from cusprocess b where a.ngay_thuchien = b.ngay_thuchien) '
IF @@admin = 0 SET @key = @key + ' and a.user_id0 = @@userId ';
SELECT @order = ' ORDER BY a.ma_kh DESC ';
SELECT @q = 'insert into #t select @@fields from dmkh0 a' + @key + @order
EXEC sp_executesql @q;
PRINT @q

SELECT * FROM #t;
DROP TABLE #t;

js.text:

function filter$searchinfo(p){
  this.constructor(p);
}
filter$searchinfo.prototype = new DirEvent();

function getTax(o, p) {
  var tax = p.valForm('ma_so_thue');
  if (tax.length != 10 && tax.length != 13) {
    $.showToast('Thông tin mã số thuế không đúng.');
    return;
  }

  $.invoke('GetTax', { taxCode: tax }, this, 30000
    , function (result) {
      if (result) {
        var obj = JSON.parse(result);
		p.valForm('ma_kh', tax, true);
        p.valForm('ten_kh', obj.Name, true);
        p.valForm('dia_chi', obj.Address, true);
		p.valForm('ten_kh2', obj.Other, true);
		p.valForm('nguoi_lh', obj.Contact, true);
		p.valForm('dien_thoai', obj.Telephone, true);

		//ma_kh, ten_kh, ten_kh2, dia_chi, ma_so_thue, nguoi_lh, dien_thoai, e_mail

		//dt.addRow([tax, obj.Name, obj.Other, obj.Address, obj.Contact, obj.Telephone],true)
		//p.appendGrid(0, dt, true);

      }
    }, function (event) {} );

}
function getSystemDate(format) {
	return new Promise(function(resolve, reject) {
		$.ajax({
			type: "POST",
			url: "/Main/Defaults.aspx/getSystemDate",
			contentType: "application/json; charset=utf-8",
			dataType: "json",
			data: JSON.stringify({ format: format }),
			success: function(response) {
				var systemDate = response.d;
				resolve(systemDate);
			},
			error: function(error) {
				reject(error);
			}
		});
	});
}
function getCurrentDate(p) {
    async function fetchCurrentDate() {
        try {
            var currentDate = await getSystemDate('dd/MM/yyyy');
            return currentDate;
        } catch (error) {
            console.error(error);
            throw error;
        }
    }
    return fetchCurrentDate();
}
function insertData (p, g, dt, rErr) {

  var maKh = p.valForm('ma_kh'), tenKh = p.valForm('ten_kh'), tenKh2 = p.valForm('ten_kh2'), masoThue = p.valForm('ma_so_thue'), diaChi = p.valForm('dia_chi'), nguoiLh = p.valForm('nguoi_lh'), dienThoai = p.valForm('dien_thoai'), eMail = p.valForm('e_mail'),  nhKh1 = p.valForm('nh_kh1'), nhKh2 = p.valForm('nh_kh2'), nhKh3 = p.valForm('nh_kh3'), ngayThuchien = p.valForm('ngay_thuchien')
  var startedTime;
  const dataNV = $.localVal('$USERINFO').Items[1];
  const dataUnit = $.localVal('$USERINFO').Items[9];
  if(masoThue == '')
  {
	$.showToast(p.msg('EmptyTax'));
	p.jObject('ma_so_thue').focus();
	return;
  }
  if(dienThoai == '')
  {
	$.showToast(p.msg('EmptyTelephone'));
	p.jObject('dien_thoai').focus();
	return;
  }
  async function fetchStartTime() {										
	try {
		startedTime = await getSystemDate('yyyy/MM/dd HH:mm:ss.FFF');
		console.log(startedTime);
		var m = new Memvars();


	var controller = 'insertKH';

	var s = window.location.href.toString();
	s = s.substring(0, s.indexOf("Main/")) + 'AppService/EService.asmx/' + "GetData";//GetValue
	//ma_kh, ten_kh, ten_kh2, ma_so_thue, dia_chi, nguoi_lh, dien_thoai, e_mail, nh_kh1, nh_kh2, nh_kh3
	m.val('ma_kh', 'C', maKh);			
	m.val('ten_kh', 'C', tenKh);			
	m.val('ten_kh2', 'C', tenKh2);
	m.val('ma_so_thue', 'C', masoThue);			
	m.val('dia_chi', 'C', diaChi);			
	m.val('nguoi_lh', 'C', nguoiLh);			
	m.val('dien_thoai', 'C', dienThoai);			
	m.val('e_mail', 'C', eMail);			
	m.val('nh_kh1', 'C', nhKh1);
	m.val('nh_kh2', 'C', nhKh2);
	m.val('nh_kh3', 'C', nhKh3);
	m.val('user_id0', 'N', dataNV);
	m.val('user_id2', 'N', dataNV);
	m.val('datetime0', 'C', startedTime);
	m.val('datetime2', 'C', startedTime);
	m.val('unit_id', 'I', dataUnit);
	m.val('ngay_thuchien', 'C', startedTime);
	//console.log(@@unit);

	$.ajax({
		type: "POST",
		url: s,
		header: '',

		data: JSON.stringify({ controller: controller, oMemvar: m.val() }),
		contentType: "application/json; charset=utf-8",
		dataType: "json",
		timeout: 30000,
		success: function (msg, s) {
			// ket qua o day
			console.log(msg.d[0])
			$.showToast(p.msg(`${msg.d[0].message}`));
			if (msg.d[0].message === 'InsertComplete') {
				<!-- //ngay_thuchien, ma_so_thue, ten_kh, ten_kh2, dia_chi, nguoi_lh, dien_thoai, e_mail, nh_kh1, nh_kh2, nh_kh3 -->
				dt.addRow([ngayThuchien, masoThue, tenKh, tenKh2, diaChi, nguoiLh, dienThoai, eMail, nhKh1, nhKh2, nhKh3 ],true)

				p.appendGrid(0, dt, true);
				p.valForm('ma_kh', '', true);
				p.valForm('ten_kh', '', true);
				p.valForm('dia_chi', '', true);
				p.valForm('ten_kh2', '', true);
				p.valForm('ma_so_thue', '', true);
				p.valForm('nguoi_lh', '', true);
				p.valForm('dien_thoai', '', true);
			} else
				p.jObject(`${msg.d[0].field}`).focus(); 

		},
		error: function (e) {
			// loi o day
			console.log(e);
		}
	});
	} catch (error) {
		console.error(error);
	}
	}
	fetchStartTime();

}
filter$searchinfo.prototype.afterInit = function(){
  var p = this._dir, g = p.grid(0), dt = g.data, rErr = '', masoThue = p.valForm('ma_so_thue');
  document.getElementById('btnTax').addEventListener('click', function() {
	getTax(this, p);
  });

  document.getElementById('btnInsert').addEventListener('click', function() {
	insertData(p, g, dt, rErr)
  });
  getCurrentDate(p)
    .then(currentDate => {
		p.valForm('ngay_thuchien', currentDate, true);
    })
    .catch(error => {
        console.error('Failed to get current date:', error);
    });
}

css.text:

#btnInsert {
	min-width: 90px;
	height: 32px;
	padding: 0;
	cursor: default;
	background-color: #188b86;
	border: 2px solid #188b86;

	display: inline-block;
	margin-bottom: 0;
	font-weight: normal;
	text-align: center;
	vertical-align: middle;
	-ms-touch-action: manipulation;
	touch-action: manipulation;
	background-image: none;
	border: 1px solid transparent;
	white-space: nowrap;
	padding: 6px 12px;
	font-size: 14px;
	line-height: 1.42857143;
	border-radius: 4px;
	-webkit-user-select: none;
	-moz-user-select: none;
	-ms-user-select: none;
	user-select: none;
	color: #fff;
	text-decoration: none;
	transition: background-color 0.3s ease;

}
#btnInsert:hover {
	background-color: #0cc99b;
	border-color: #6FB98F;
	text-decoration: none;
	border: 2px solid #188b86;
}
